add_action( 'rest_api_init', function () { register_rest_route( 'nadlan-dbg/v1', '/doms', array( 'methods' => 'GET', 'permission_callback' => function(){ return current_user_can('manage_options'); }, 'callback' => function () { global $wpdb; $rows = $wpdb->get_results( "SELECT meta_value, COUNT(*) c FROM {$wpdb->postmeta} pm JOIN {$wpdb->posts} p ON p.ID=pm.post_id WHERE pm.meta_key='enc_domain' AND p.post_type='nadlan_term' GROUP BY meta_value ORDER BY c DESC", ARRAY_A ); return $rows; } ) ); } );